```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { CheckoutForm } from './CheckoutForm';

expect.extend(toHaveNoViolations);

describe('CheckoutForm', () => {
  const mockOnSubmit = vi.fn();
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes checkout when all fields valid', async () => {
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} />);

      await user.type(screen.getByRole('textbox', { name: /street address/i }), '123 Main St');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'New York');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiration/i }), '12/25');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('heading', { name: /order confirmed/i })).toBeInTheDocument();
      });
    });
  });

  describe('Form Validation - Liability Exposure Points', () => {
    it('displays error when credit card format invalid', async () => {
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} />);

      await user.type(screen.getByRole('textbox', { name: /card number/i }), '123');
      await user.tab();

      expect(screen.getByRole('alert')).toHaveTextContent(/invalid card number/i);
    });

    it('prevents submission with empty required fields', async () => {
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} />);

      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getAllByRole('alert')).toHaveLength(expect.any(Number));
      expect(mockOnSubmit).not.toHaveBeenCalled();
    });
  });

  describe('Error Recovery - What Prosecutors Look For', () => {
    it('allows retry after payment failure', async () => {
      mockOnSubmit.mockRejectedValueOnce(new Error('Payment declined'));
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} />);

      // Complete form and submit...
      await waitFor(() => {
        expect(screen.getByRole('button', { name: /try again/i })).toBeEnabled();
      });
    });
  });

  describe('Edge Cases - Where Lawsuits Originate', () => {
    it('redirects when cart empty', () => {
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[]} />);

      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
    });

    it('handles session timeout gracefully', async () => {
      vi.useFakeTimers();
      render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} sessionTimeout={300000} />);

      vi.advanceTimersByTime(300001);

      expect(screen.getByRole('dialog', { name: /session expired/i })).toBeInTheDocument();
      vi.useRealTimers();
    });
  });

  describe('Accessibility - ADA Compliance Requirements', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<CheckoutForm onSubmit={mockOnSubmit} cartItems={[{ id: 1 }]} />);

      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
